package ama.storage;
import ama.transcript.*;import ama.model.*;import ama.task.*;import ama.worker.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class Task09CandidatePaginationIT extends Task09MinutesHttpIT {
 @Override void afterExternal(Map<String,Object> first,MinutesExternalPreparation preparation,ControlledMinutesClient client,JdbcExternalOperations ignored)throws Exception {
  var authority=ama.api.Task09RuntimeProbe.components(app).authority();var prep=new JdbcMinutesGenerationPreparation(authority,this::snapshot,pin,prompt,model,new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,33554432,128,256,256));var outbox=new JdbcOutbox(source,new MinutesEventReferences(source).validators());var queue=new JdbcTaskQueue(source,new JdbcSubjectFences(source,Set.of("MEETING")),outbox,Map.of("MINUTES_GENERATE_V1",authority.minutesTaskPolicy()));var operations=new JdbcExternalOperations(queue);var permits=new JdbcModelPermitPool(operations,Map.of(ControlledMinutesProtocol.MODEL,new ModelConfiguration(ControlledMinutesProtocol.MODEL,1,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT)),(t,m,d)->{throw new IllegalStateException();});var commands=new JdbcMinutesGenerationCommands(authority,prep,queue,outbox,new ama.audit.JdbcAuditAdapter(source));var handler=new MinutesGenerationHandler(preparation,client,operations,permits);var candidates=new ArrayList<Map<String,Object>>();candidates.add(first);
  try(var worker=WorkerLoop.external(queue,operations,permits,Map.of("MINUTES_GENERATE",1),Map.of("MINUTES_GENERATE_V1",handler),Map.of("MINUTES_GENERATE_V1",ControlledMinutesProtocol.MODEL),"TASK09_CANDIDATE_PAGES")){
   for(int n=0;n<3;n++)candidates.add(produce(commands,worker));
   var root=j.queryForMap("SELECT * FROM meeting WHERE id=?",meeting);var receipts=new ArrayList<Map<String,Object>>();var access=app.getBean(ama.access.MeetingAccess.class);
   for(int n=1;n<4;n++){var before=candidates.get(n);String state=List.of("PENDING","ADOPTED","REJECTED","STALE").get(n);new ama.db.TransactionRunner(source).required(()->{access.require(access.lock(actor(),meeting),ama.access.MeetingAccess.Action.EDIT);assertEquals(before,j.queryForMap("SELECT * FROM generation_candidate WHERE id=? FOR UPDATE",before.get("id")));assertEquals(1,j.update("UPDATE generation_candidate SET state=?,decided_at=UTC_TIMESTAMP(6) WHERE id=? AND meeting_id=? AND state='PENDING' AND decided_at IS NULL",state,before.get("id"),meeting));return null;});var after=j.queryForMap("SELECT * FROM generation_candidate WHERE id=?",before.get("id"));var restored=new LinkedHashMap<>(after);restored.put("state",before.get("state"));restored.put("decided_at",before.get("decided_at"));assertEquals(before,restored);receipts.add(Map.of("before",strings(before),"after",strings(after)));}assertEquals(root,j.queryForMap("SELECT * FROM meeting WHERE id=?",meeting));restartApi();String base="/meetings/"+meeting+"/minutes/candidates";
   var one=call("GET",base+"?state=ALL&limit=2","",null);assertEquals(200,one.statusCode(),one.body());String cursor=body(one).get("nextCursor").asText();var later=produce(commands,worker);var two=call("GET",base+"?state=ALL&limit=2&cursor="+cursor,"",null);assertEquals(200,two.statusCode(),two.body());assertEquals(2,body(two).get("items").size());assertTrue(body(two).get("nextCursor").isNull());var ids=new HashSet<String>();var states=new HashSet<String>();for(var page:List.of(body(one),body(two)))for(var row:page.get("items")){ids.add(row.get("candidateId").asText());states.add(row.get("state").asText());}assertEquals(candidates.stream().map(c->(String)c.get("id")).collect(java.util.stream.Collectors.toSet()),ids);assertEquals(Set.of("PENDING","ADOPTED","REJECTED","STALE"),states);assertFalse(ids.contains(later.get("id")));
   assertEquals(400,call("GET",base+"?state=PENDING&cursor="+cursor,"",null).statusCode());assertEquals(400,call("GET",base+"?state=ALL&cursor="+cursor+"x","",null).statusCode());String oldMeeting=meeting;newMeeting();assertEquals(400,call("GET","/meetings/"+meeting+"/minutes/candidates?state=ALL&cursor="+cursor,"",null).statusCode());meeting=oldMeeting;for(String state:List.of("PENDING","ADOPTED","REJECTED","STALE")){var page=call("GET",base+"?state="+state,"",null);assertEquals(200,page.statusCode(),page.body());assertEquals(state.equals("PENDING")?2:1,body(page).get("items").size());assertTrue(body(page).get("nextCursor").isNull());}
   java.nio.file.Files.writeString(receipt.resolve("four-state-candidate-pagination.json"),json.writeValueAsString(Map.of("qualification","Task9 structural disposition only, not Task10 adoption","dispositions",receipts,"ids",ids,"states",states,"laterExcluded",later.get("id"),"crossMeetingAndFilterRejected",true,"tailCursorNull",true)));
  }
 }
 Map<String,Object> produce(JdbcMinutesGenerationCommands commands,WorkerLoop worker)throws Exception{var accepted=(Map<?,?>)commands.enqueue(actor(),meeting,UUID.randomUUID().toString(),4,UUID.randomUUID().toString()).get("result");String task=(String)accepted.get("taskId");worker.pollOnce("MINUTES_GENERATE");long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(30);while(System.nanoTime()<end&&j.queryForObject("SELECT COUNT(*) FROM durable_task t LEFT JOIN external_execution e ON e.task_id=t.id LEFT JOIN model_reservation r ON r.execution_id=e.id WHERE t.id=? AND t.state='SUCCEEDED' AND r.settled_at IS NOT NULL",Integer.class,task)==0)Thread.sleep(25);assertEquals("SUCCEEDED",j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,task));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM model_reservation r JOIN external_execution e ON e.id=r.execution_id WHERE e.task_id=? AND r.settled_at IS NULL",Integer.class,task));return j.queryForMap("SELECT * FROM generation_candidate WHERE task_id=?",task);}
 static Map<String,String> strings(Map<String,Object> row){var out=new LinkedHashMap<String,String>();row.forEach((k,v)->out.put(k,v==null?null:v.toString()));return out;}
}
